mapper.select:
SELECT id, course_id, day_number, title, created_at, updated_at
FROM course_days WHERE course_id = #{courseId}
ORDER BY day_number ASC, id ASC

mapper.update:
UPDATE course_days SET day_number = day_number + #{offset}
WHERE course_id = #{courseId}
ORDER BY day_number DESC

UPDATE courses SET country_id = (
    SELECT country_id FROM course_countries
    WHERE course_id = #{courseId} ORDER BY display_order ASC LIMIT 1
) WHERE id = #{courseId}
